import numpy as np
from scipy.optimize import minimize

def objective(x):
    return - (np.sum(x**2) + np.sum(x)**2)

def constraint_s(x):
    return 1 - np.abs(np.sum(x))

def solve(n):
    cons = {'type': 'ineq', 'fun': constraint_s}
    bounds = [(-1 + 1e-9, 1 - 1e-9)] * n

    best_f = -np.inf
    # Try different starting points to avoid local minima
    for _ in range(10):
        x0 = np.random.uniform(-0.9, 0.9, n)
        res = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            if -res.fun > best_f:
                best_f = -res.fun
                best_x = res.x

    return best_f, best_x

for n in [20, 21, 22]:
    f_max, x_opt = solve(n)
    print(f"n={n}, max_f={f_max}")
